import"//resources/cr_elements/cr_radio_button/cr_radio_button.js";import"//resources/cr_elements/cr_radio_group/cr_radio_group.js";import{PolymerElement}from"//resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{prefToString,stringToPrefValue}from"chrome://resources/cr_components/settings_prefs/pref_util.js";import{PrefControlMixin}from"./pref_control_mixin.js";import{getTemplate}from"./settings_radio_group.html.js";const SettingsRadioGroupElementBase=PrefControlMixin(PolymerElement);export class SettingsRadioGroupElement extends SettingsRadioGroupElementBase{static get is(){return"settings-radio-group"}static get template(){return getTemplate()}static get properties(){return{groupAriaLabel:String,noSetPref:{type:Boolean,value:false},selected:String,selectableElements:{type:String,value:["cr-radio-button","controlled-radio-button"].join(", ")}}}static get observers(){return["resetToPrefValue(pref.*)"]}ready(){super.ready();this.setAttribute("role","none")}focus(){this.shadowRoot.querySelector("cr-radio-group").focus()}resetToPrefValue(){this.selected=prefToString(this.pref)}sendPrefChange(){if(!this.pref){return}this.set("pref.value",stringToPrefValue(this.selected,this.pref))}onSelectedChanged_(){this.selected=this.shadowRoot.querySelector("cr-radio-group").selected;if(!this.noSetPref){this.sendPrefChange()}this.dispatchEvent(new CustomEvent("change",{bubbles:true,composed:true}))}}customElements.define(SettingsRadioGroupElement.is,SettingsRadioGroupElement);